def tokenize(text):
    return text.replace("(", " ( ").replace(")", " ) ").split()

def read(tokens):
    token = tokens.pop(0)
    if token == "(":
        items = []
        while tokens[0] != ")":
            items.append(read(tokens))
        tokens.pop(0)                      # the closing )
        return items
    try:
        return int(token)
    except ValueError:
        return token                       # a symbol, kept as a string


# Step 3: a symbol table, the same dictionary as the calculator with variables.
PRIMITIVES = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "=": lambda a, b: a == b,
    "<": lambda a, b: a < b,
}
symbols = dict(PRIMITIVES)

def evaluate(x):
    if isinstance(x, int):
        return x
    if isinstance(x, str):
        if x not in symbols:
            raise NameError(f"undefined name {x}")
        return symbols[x]                   # lookup
    if x[0] == "define":
        symbols[x[1]] = evaluate(x[2])      # assignment
        return None
    function, *args = [evaluate(part) for part in x]
    return function(*args)


def run(text):
    tokens = tokenize(text)
    while tokens:
        result = evaluate(read(tokens))
        if result is not None:
            print(result)


run("""
(define x 3)
(define y (+ (* x 2) 1))
y
(* x y)
""")
